public class Solution {
    static class Node {
        int val;
        Node next;
        Node(int val) { this.val = val; }
    }

    // Floyd: se há ciclo, o rápido alcança o lento dentro dele. O(n), O(1).
    static boolean temCiclo(Node head) {
        Node lento = head, rapido = head;
        while (rapido != null && rapido.next != null) {
            lento = lento.next;
            rapido = rapido.next.next;
            if (lento == rapido) return true;
        }
        return false;
    }

    // Quando o rápido chega ao fim, o lento está no meio. O(n), O(1).
    static Node meio(Node head) {
        Node lento = head, rapido = head;
        while (rapido != null && rapido.next != null) {
            lento = lento.next;
            rapido = rapido.next.next;
        }
        return lento;
    }
}

