import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    private static Solution.Node lista(int... vals) {
        Solution.Node head = null, tail = null;
        for (int v : vals) {
            var n = new Solution.Node(v);
            if (head == null) head = n; else tail.next = n;
            tail = n;
        }
        return head;
    }

    @Test void semCiclo() {
        assertFalse(Solution.temCiclo(null));
        assertFalse(Solution.temCiclo(lista(1)));
        assertFalse(Solution.temCiclo(lista(1, 2, 3, 4)));
    }

    @Test void comCiclo() {
        var head = lista(1, 2, 3, 4, 5);
        head.next.next.next.next.next = head.next.next; // 5 -> 3
        assertTrue(Solution.temCiclo(head));
        var um = lista(7);
        um.next = um;
        assertTrue(Solution.temCiclo(um));
    }

    @Test void meioImparEPar() {
        assertEquals(3, Solution.meio(lista(1, 2, 3, 4, 5)).val);
        assertEquals(4, Solution.meio(lista(1, 2, 3, 4, 5, 6)).val);
        assertEquals(9, Solution.meio(lista(9)).val);
        assertNull(Solution.meio(null));
    }

    @Test void listaGrandeComCicloLongo() {
        var head = lista(java.util.stream.IntStream.range(0, 200_000).toArray());
        var fim = head;
        while (fim.next != null) fim = fim.next;
        fim.next = head;
        assertTrue(Solution.temCiclo(head));
    }
}
